// ─────────────────────────────────────────────────────────────────────────
// LIBRERIA ITINERARI — CATALOGO AGGIUNTIVO (22/08/2026)
//
// Solo DATI, nessun import: come libraryZonesWorld.ts. Viene fuso nei
// cataloghi di libraryDescriptors.ts (THEMES.places e WORLD_ZONES) e produce
// ~5.000 descrittori in più, distribuiti su TUTTE le categorie editoriali:
//   • EXTRA_WORLD_ZONES: zone mondiali nuove × 2 durate × 8 angoli = 16 l'una
//   • EXTRA_THEME_PLACES: luoghi nuovi per ciascuno dei 17 temi × 3 varianti
//     (tema / 🆓 gratis / 🎟 prenotabile) = 3 l'uno
//
// Le REGOLE sono quelle del catalogo principale e non hanno eccezioni:
//   - ogni luogo è REALE e l'aggancio nella nota è verificabile: è il
//     materiale che entra nel brief, non un abbellimento;
//   - le coordinate sono il punto di riferimento turistico (centro storico,
//     molo, stazione del trenino), non il centroide amministrativo: la
//     verifica in codice confronta le tappe con questa ancora (30 km);
//   - niente doppioni: un luogo già presente nel tema principale viene
//     scartato in fase di fusione (vedi mergeExtraThemePlaces).
// ─────────────────────────────────────────────────────────────────────────

export interface ExtraZone {
  c: string; k: string; lat: number; lon: number; t: 1 | 2 | 3; n: string;
}

export interface ExtraThemePlace {
  city: string; country: string; lat: number; lon: number; note?: string; days?: number;
}

